"""Publish a truthful completed-search status from immutable event receipts."""
from pathlib import Path
import argparse,json
from datetime import datetime
ap=argparse.ArgumentParser();ap.add_argument('base',type=Path);a=ap.parse_args();base=a.base.resolve();root=base/'stage2';frozen=json.loads((root/'final-accepted/frozen.json').read_text());epochs=[root,root/'margin3',root/'closer-packing',root/'margin2'];events=[e for folder in epochs for e in json.loads((folder/'events.json').read_text())];started=min(datetime.fromisoformat(e['started_at']) for e in events);ended=max(datetime.fromisoformat(e['finished_at']) for e in events);last=max(events,key=lambda e:e['finished_at']);status={'schema':1,'size_family':'small-loop','stage':'stage2','status':'completed','operation':'Search completed; retained board independently audited and frozen','running':False,'active_pid':None,'active_operation_started_at':None,'active_operation_elapsed_seconds':None,'search_started_at':started.isoformat(),'search_finished_at':ended.isoformat(),'search_elapsed_seconds':(ended-started).total_seconds(),'last_completion_at':frozen['frozen_at'],'completed_trials':len(events),'fully_routed_trials':sum(e['routing_attempted'] for e in events),'retained_improvements':sum(e['retained'] for e in events),'latest_completed_trial':{'folder':last['folder'],'finished_at':last['finished_at'],'valid':last['result']['valid'],'candidate_score':last['result']['official_formula_score'],'retained':last['retained']},'retained':{'folder':str(root/'final-accepted'),'board_sha256':frozen['score']['board_sha256'],'official_formula_score':frozen['score']['official_formula_score'],'valid':True},'epochs':[str(f/'events.json') for f in epochs],'source_sha':frozen['source_sha'],'note':'No live router geometry is available. Display only saved completed boards; playback is historical.'};p=root/'live-status.json';temp=p.with_suffix('.tmp');temp.write_text(json.dumps(status,indent=2));temp.replace(p);print(p)
